// Phase 2A — Entity schemas for the scan / scoring / profile model.
//
// PURPOSE: Define the six required contract entities as pure factories (fill safe defaults) + pure
// validators (return {valid, errors}, NEVER throw) so missing/invalid data is DETECTED by tests, not
// silently accepted. No scoring logic lives here — only shape + validation.
//
// ASSUMPTIONS / NON-OBVIOUS LOGIC:
// - MISCHIEF_AXES is the canonical set of mischief dimensions the scans + games inform. It is derived
//   STRICTLY from the design-bible FUNNEL table (§99): Fenrir→timing, Jormungandr→routing, Hel→triage,
//   Sleipnir→parallelism, Rune Cast→reflection. Ratatoskr is spec-unresolved and is intentionally NOT
//   given a scored axis (it maps to `unresolved: true` in gameSurveyMap.js).
// - `signal` vectors on answer options and on game signals are keyed by these axes. Until the weight
//   matrix + full question set are recovered, these vectors are empty — the engine tolerates that.
// - `Answer.valid` is SERVER-resolved and must never be trusted from a client payload (kept explicit).

export const MISCHIEF_AXES = ['timing', 'routing', 'triage', 'parallelism', 'reflection'];

// ---------------------------------------------------------------------------
// ScanQuestion
// ---------------------------------------------------------------------------
function normalizeOption(o = {}) {
  return {
    id: o.id ?? '',
    label: o.label ?? '',
    // signal weights toward mischief axes; empty until the weight matrix is recovered
    signals: o.signals && typeof o.signals === 'object' ? { ...o.signals } : {},
  };
}

export function createScanQuestion(input = {}) {
  return {
    id: input.id ?? '',
    scanId: input.scanId ?? '',
    text: input.text ?? '',
    options: Array.isArray(input.options) ? input.options.map(normalizeOption) : [],
    axis: input.axis ?? null,
    weight: typeof input.weight === 'number' ? input.weight : 1,
    source: input.source ?? 'placeholder',
    confidence: input.confidence ?? 'none',
    required: input.required ?? true,
  };
}

export function validateScanQuestion(q) {
  const errors = [];
  if (!q || typeof q !== 'object') return { valid: false, errors: ['question must be an object'] };
  if (!q.id) errors.push('question.id is required');
  if (!q.scanId) errors.push('question.scanId is required');
  if (!q.text) errors.push('question.text is required');
  if (!Array.isArray(q.options) || q.options.length === 0) {
    errors.push('question.options must be a non-empty array');
  } else {
    for (const opt of q.options) {
      if (!opt.id) errors.push(`option missing id (question ${q.id || '?'})`);
      for (const ax of Object.keys(opt.signals || {})) {
        if (!MISCHIEF_AXES.includes(ax)) errors.push(`option signal axis "${ax}" is not a known mischief axis`);
        else if (typeof opt.signals[ax] !== 'number' || Number.isNaN(opt.signals[ax])) {
          errors.push(`option signal for "${ax}" must be a number`);
        }
      }
    }
  }
  if (q.axis !== null && !MISCHIEF_AXES.includes(q.axis)) errors.push(`question.axis "${q.axis}" is not a known mischief axis`);
  if (typeof q.weight !== 'number' || q.weight < 0 || Number.isNaN(q.weight)) errors.push('question.weight must be a non-negative number');
  return { valid: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// Answer
// ---------------------------------------------------------------------------
export function createAnswer(input = {}) {
  return {
    questionId: input.questionId ?? '',
    scanId: input.scanId ?? '',
    optionId: input.optionId ?? null, // null = skipped / no selection
    value: input.value ?? null,
    answeredAt: input.answeredAt ?? null,
    valid: input.valid ?? false, // server-resolved; never trusted from client
  };
}

export function validateAnswer(a) {
  const errors = [];
  if (!a || typeof a !== 'object') return { valid: false, errors: ['answer must be an object'] };
  if (!a.questionId) errors.push('answer.questionId is required');
  if (!a.scanId) errors.push('answer.scanId is required');
  // optionId === null is a LEGAL skipped answer; only a non-string non-null is invalid.
  if (a.optionId !== null && typeof a.optionId !== 'string') errors.push('answer.optionId must be null or a string');
  if (a.answeredAt !== null && (typeof a.answeredAt !== 'string' || Number.isNaN(Date.parse(a.answeredAt)))) {
    errors.push('answer.answeredAt must be null or an ISO date string');
  }
  return { valid: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// GameSignal
// ---------------------------------------------------------------------------
export function emptyAxes(obj = {}) {
  const o = {};
  for (const ax of MISCHIEF_AXES) o[ax] = typeof obj[ax] === 'number' ? obj[ax] : 0;
  return o;
}

export function createGameSignal(input = {}) {
  return {
    gameId: input.gameId ?? '',
    axisContributions: emptyAxes(input.axisContributions),
    raw: input.raw ?? null, // the source GameResult, kept for audit
    playedAt: input.playedAt ?? null,
    unresolved: input.unresolved ?? false, // true for Ratatoskr (spec unresolved)
  };
}

export function validateGameSignal(g) {
  const errors = [];
  if (!g || typeof g !== 'object') return { valid: false, errors: ['gameSignal must be an object'] };
  if (!g.gameId) errors.push('gameSignal.gameId is required');
  if (!g.axisContributions || typeof g.axisContributions !== 'object') {
    errors.push('gameSignal.axisContributions is required');
  } else {
    for (const ax of MISCHIEF_AXES) {
      const v = g.axisContributions[ax];
      if (typeof v !== 'number' || Number.isNaN(v)) errors.push(`gameSignal.axisContributions.${ax} must be a number`);
    }
  }
  return { valid: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// ScoreBreakdown
// ---------------------------------------------------------------------------
export function createScoreBreakdown(input = {}) {
  return {
    scanId: input.scanId ?? '',
    axes: input.axes ?? emptyAxes(), // { axis: { score, max, pct } }
    totals: input.totals ?? { raw: 0, max: 100, normalized: 0 },
    surveyContrib: input.surveyContrib ?? emptyAxes(),
    gameSignalContrib: input.gameSignalContrib ?? emptyAxes(),
    computedAt: input.computedAt ?? null,
    modelVersions: input.modelVersions ?? null,
  };
}

export function validateScoreBreakdown(b) {
  const errors = [];
  if (!b || typeof b !== 'object') return { valid: false, errors: ['scoreBreakdown must be an object'] };
  if (!b.axes || typeof b.axes !== 'object') errors.push('scoreBreakdown.axes is required');
  else for (const ax of MISCHIEF_AXES) {
    const a = b.axes[ax];
    if (!a || typeof a.score !== 'number' || typeof a.pct !== 'number') errors.push(`scoreBreakdown.axes.${ax} malformed`);
  }
  for (const key of ['surveyContrib', 'gameSignalContrib']) {
    if (!b[key] || typeof b[key] !== 'object') errors.push(`scoreBreakdown.${key} is required`);
  }
  return { valid: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// ArchetypeResult
// ---------------------------------------------------------------------------
export function createArchetypeResult(input = {}) {
  return {
    archetypeId: input.archetypeId ?? '',
    name: input.name ?? '',
    score: typeof input.score === 'number' ? input.score : 0,
    rank: typeof input.rank === 'number' ? input.rank : 0,
    isPrimary: input.isPrimary ?? false,
    matchedAxes: Array.isArray(input.matchedAxes) ? input.matchedAxes : [],
    confidence: input.confidence ?? 'none', // 'none' until the weight matrix is recovered
    evidence: input.evidence ?? { surveySignal: 0, gameSignal: 0 },
  };
}

export function validateArchetypeResult(r) {
  const errors = [];
  if (!r || typeof r !== 'object') return { valid: false, errors: ['archetypeResult must be an object'] };
  if (!r.archetypeId) errors.push('archetypeResult.archetypeId is required');
  if (typeof r.score !== 'number' || Number.isNaN(r.score)) errors.push('archetypeResult.score must be a number');
  if (typeof r.rank !== 'number') errors.push('archetypeResult.rank must be a number');
  if (!['none', 'low', 'medium', 'high'].includes(r.confidence)) errors.push('archetypeResult.confidence must be none|low|medium|high');
  return { valid: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// PersistenceRecord
// ---------------------------------------------------------------------------
export function createPersistenceRecord(input = {}) {
  return {
    recordId: input.recordId ?? '',
    playerId: input.playerId ?? 'anonymous',
    scanId: input.scanId ?? '',
    answers: Array.isArray(input.answers) ? input.answers : [],
    gameSignals: Array.isArray(input.gameSignals) ? input.gameSignals : [],
    scoreBreakdown: input.scoreBreakdown ?? null,
    archetypeResults: Array.isArray(input.archetypeResults) ? input.archetypeResults : [],
    createdAt: input.createdAt ?? null,
    completedAt: input.completedAt ?? null,
    modelVersions: input.modelVersions ?? null,
    schemaVersion: input.schemaVersion ?? null,
  };
}

export function validatePersistenceRecord(r) {
  const errors = [];
  if (!r || typeof r !== 'object') return { valid: false, errors: ['record must be an object'] };
  if (!r.recordId) errors.push('record.recordId is required');
  if (!r.scanId) errors.push('record.scanId is required');
  if (!Array.isArray(r.answers)) errors.push('record.answers must be an array');
  if (!Array.isArray(r.gameSignals)) errors.push('record.gameSignals must be an array');
  if (r.modelVersions) {
    for (const ax of ['schemaVersion', 'questionSetVersion', 'formulaVersion', 'archetypeModelVersion']) {
      if (!r.modelVersions[ax]) errors.push(`record.modelVersions.${ax} is required`);
    }
  }
  return { valid: errors.length === 0, errors };
}
