import { RATATOSKR_DECISION } from './contentImport.js';

export const RATATOSKR_PRODUCT_DECISION = Object.freeze({
  decision: RATATOSKR_DECISION.RETAIN_ENGAGEMENT,
  status: 'approved',
  mode: 'engagement-only',
  scoringContribution: 0,
  affectsArchetype: false,
  affectsConfidence: false,
  affectsProducts: false,
  partOfScanModel: false,
  resolvedAt: '2026-08-12',
});

// Pure: given any game signals, EXCLUDE Ratatoskr from scan context before it reaches the engine.
// Returns a new array with Ratatoskr (unresolved) signals removed so they can never be scored.
export function excludeRatatoskrFromScanContext(gameSignals = []) {
  return gameSignals.filter((g) => g && g.gameId !== 'ratatoskr');
}

// Pure: engagement metadata is allowed to be recorded (separately, not as a scan signal).
export function ratatoskrEngagementMeta(playCount = 0, lastPlayedAt = null) {
  return { gameId: 'ratatoskr', engagementOnly: true, playCount, lastPlayedAt, scored: false };
}
