// Route table — Phase 1A + Phase 2C (REFLECTION added). Hash-backed so refresh / back / forward are
// real browser navigations (no router lib). Each route is a stable string in window.location.hash.
export const ROUTES = {
  HOME: '#/home',
  GAMES: '#/games',
  GAME: (id) => `#/game/${id}`,
  DIAGNOSTICS: '#/diagnostics',
  SURVEY: (id) => `#/survey/${id}`,
  REFLECTION: '#/reflection',
  SERVICES: '#/services',
  PRODUCTS: '#/products',
  DIRECTORY: '#/directory',
  BLOG: '#/blog',
};

// Parse the current hash into { name, params }.
export function parseHash(hash = window.location.hash) {
  const raw = (hash || '').replace(/^#\/?/, ''); // strip "#/" or "#"
  if (!raw || raw === 'home') return { name: 'home', params: {} };
  const parts = raw.split('/');
  switch (parts[0]) {
    case 'games': return { name: 'games', params: {} };
    case 'game': return { name: 'game', params: { id: parts[1] || null } };
    case 'diagnostics': return { name: 'diagnostics', params: {} };
    case 'survey': return { name: 'survey', params: { id: parts[1] || null } };
    case 'reflection': return { name: 'reflection', params: {} };
    case 'services': return { name: 'services', params: {} };
    case 'products': return { name: 'products', params: {} };
    case 'directory': return { name: 'directory', params: {} };
    case 'blog': return { name: 'blog', params: {} };
    default: return { name: 'home', params: {} };
  }
}
