// Phase 2B — Content-import schemas (authorization: "prepare content-import schemas").
//
// PURPOSE: Define the SHAPE Loki must supply before full scan behavior can be activated. These are
// pure factories + validators (return {valid,errors}, never throw). NO content is invented here — the
// example fixtures that exercise these live in examples.nonprod.js and are flagged non-production.
//
// THREE LAYERS (see docs/phase-2a-missing-content.md "Three separate models"):
//   1. Question inventory      -> createScanQuestionContent
//   2. Answer-to-score model    -> createAnswerScoreRule  (the 5 required weights)
//   3. Score-to-archetype model -> createScoreToArchetypeRule
// Plus the Ratatoskr decision enum.
//
// ASSUMPTIONS / NON-OBVIOUS LOGIC:
// - The 5 answer weights (friction/visibility/ownership/readiness/opportunity) are the EXACT fields named
//   in the Phase 2B authorization. They are required (missing => invalid) so a partial model can never
//   silently pass validation.
// - `scoreDimensions` defaults to the canonical MISCHIEF_AXES; an approved model MAY redefine dimensions,
//   but the validator requires them to be a non-empty array of strings.
// - `minCompletion` = minimum number of answered questions required before a profile may be produced. The
//   engine's "missing-answer behavior" is driven by this in modelRunner.js.

import { MISCHIEF_AXES } from './schemas.js';

export const RATATOSKR_DECISION = Object.freeze({
  EXCLUDE: 'exclude',              // never scored
  PROVIDE_SPEC: 'provide-spec',    // Loki supplies a spec + signal model
  RETAIN_ENGAGEMENT: 'retain-engagement-only', // zero contribution, engagement only
});

// PROVISIONAL implementation default ONLY — NOT an approved product decision. Pending Loki confirmation
// (review recommended "engagement-only, zero scoring contribution"; Hermes has NOT adopted it as approved).
// Until Loki confirms, Ratatoskr's treatment is UNDECIDED at the product level.
export const CURRENT_RATATOSKR_DECISION = RATATOSKR_DECISION.RETAIN_ENGAGEMENT;

// --- 1) Question inventory -------------------------------------------------
export function createScanQuestionContent(input = {}) {
  return {
    questionId: input.questionId ?? '',
    scanId: input.scanId ?? '',
    questionText: input.questionText ?? '',
    answerOptions: Array.isArray(input.answerOptions)
      ? input.answerOptions.map((o) => ({ value: o.value ?? '', label: o.label ?? '', scale: o.scale ?? null }))
      : [],
    displayOrder: typeof input.displayOrder === 'number' ? input.displayOrder : 0,
    source: input.source ?? 'unavailable',
    confidence: input.confidence ?? 'none',
  };
}

export function validateScanQuestionContent(q) {
  const errors = [];
  if (!q || typeof q !== 'object') return { valid: false, errors: ['questionContent must be an object'] };
  if (!q.questionId) errors.push('questionContent.questionId required');
  if (!q.scanId) errors.push('questionContent.scanId required');
  if (!q.questionText) errors.push('questionContent.questionText required (no invented copy allowed)');
  if (!Array.isArray(q.answerOptions) || q.answerOptions.length === 0) errors.push('questionContent.answerOptions must be non-empty');
  else for (const o of q.answerOptions) {
    if (o.value === '' || o.value == null) errors.push(`answerOption missing value (q ${q.questionId})`);
  }
  if (typeof q.displayOrder !== 'number') errors.push('questionContent.displayOrder must be a number');
  return { valid: errors.length === 0, errors };
}

// --- 2) Answer-to-score model (the 5 required weights) ----------------------
const ANSWER_WEIGHT_KEYS = ['frictionWeight', 'visibilityWeight', 'ownershipWeight', 'readinessWeight', 'opportunityWeight'];

export function createAnswerScoreRule(input = {}) {
  const rule = { questionId: input.questionId ?? '', answerValue: input.answerValue ?? '' };
  // IMPORTANT: do NOT default missing weights to 0 — an absent weight must fail validation (a 0 weight
  // is a legitimate present value; "missing" must be distinguishable from "zero"). Leave undefined.
  for (const k of ANSWER_WEIGHT_KEYS) rule[k] = input[k];
  return rule;
}

export function validateAnswerScoreRule(r) {
  const errors = [];
  if (!r || typeof r !== 'object') return { valid: false, errors: ['answerScoreRule must be an object'] };
  if (!r.questionId) errors.push('answerScoreRule.questionId required');
  if (r.answerValue === '' || r.answerValue == null) errors.push('answerScoreRule.answerValue required');
  for (const k of ANSWER_WEIGHT_KEYS) {
    if (typeof r[k] !== 'number' || Number.isNaN(r[k])) errors.push(`answerScoreRule.${k} must be a number`);
  }
  return { valid: errors.length === 0, errors };
}

// --- 3) Score-to-archetype model -------------------------------------------
export function createScoreToArchetypeRule(input = {}) {
  return {
    scoreDimensions: Array.isArray(input.scoreDimensions) && input.scoreDimensions.length ? input.scoreDimensions : [...MISCHIEF_AXES],
    normalization: input.normalization ?? 'none', // 'none' | 'min-max' | 'zscore' (approved model defines)
    tieHandling: input.tieHandling ?? 'shared-rank', // 'shared-rank' | 'first' (approved model defines)
    minCompletion: typeof input.minCompletion === 'number' ? input.minCompletion : 0,
    archetypeThresholds: input.archetypeThresholds && typeof input.archetypeThresholds === 'object' ? input.archetypeThresholds : {},
    confidenceRules: input.confidenceRules && typeof input.confidenceRules === 'object' ? input.confidenceRules : {},
    fallback: input.fallback ?? 'no-result', // 'no-result' | 'lowest-axis' (approved model defines)
  };
}

export function validateScoreToArchetypeRule(r) {
  const errors = [];
  if (!r || typeof r !== 'object') return { valid: false, errors: ['scoreToArchetypeRule must be an object'] };
  if (!Array.isArray(r.scoreDimensions) || r.scoreDimensions.length === 0) errors.push('scoreToArchetypeRule.scoreDimensions must be a non-empty array');
  if (!['none', 'min-max', 'zscore'].includes(r.normalization)) errors.push('scoreToArchetypeRule.normalization must be none|min-max|zscore');
  if (!['shared-rank', 'first'].includes(r.tieHandling)) errors.push('scoreToArchetypeRule.tieHandling must be shared-rank|first');
  if (typeof r.minCompletion !== 'number' || r.minCompletion < 0) errors.push('scoreToArchetypeRule.minCompletion must be a non-negative number');
  if (!['no-result', 'lowest-axis'].includes(r.fallback)) errors.push('scoreToArchetypeRule.fallback must be no-result|lowest-axis');
  return { valid: errors.length === 0, errors };
}

export { ANSWER_WEIGHT_KEYS, MISCHIEF_AXES };
