// Phase 3A — Canonical product/service catalog schema (Path B era; pre-checkout).
//
// PURPOSE: A single authoritative contract separating PRODUCTS (purchasable deliverables/digital goods)
// from SERVICES (paid engagements / advisory personas). Each has stable IDs, a status lifecycle, and
// pure validators. No pricing/URL is invented; status drives purchasability.
//
// SEPARATION (authorization: "separate products from services"):
//   - Products  = digital goods / templates / vault items. Source today: gumroadProducts (3 DRAFTS).
//   - Services  = paid engagements / archetype personas. Source today: data/archetypes.js (14 personas).
//   These were previously conflated in the Services view; now distinct record kinds.
//
// STATUS LIFECYCLE (authorization: "add status fields", "status lifecycle defined"):
//   draft        -> not purchasable (Gumroad drafts stay here; Phase 0B rule preserved)
//   planned      -> defined, not yet available
//   available    -> live, purchasable (none today — no URL invented, so none are 'available')
//   retired      -> removed from active catalog
//   RULE: only status === 'available' AND checkoutEligible === true may be purchasable. Drafts are
//   structurally non-purchasable regardless of any URL field (which we do not populate — "do not invent
//   product URLs").
//
// ARCHETYPE REFERENCE (authorization: "validate archetype references structurally"):
//   A service MAY reference one or more archetypeIds (the persona it embodies). Referenced IDs must exist
//   in the archetype catalog; structural validation only (no inference, no scoring mapping).

export const CATALOG_KIND = Object.freeze({ PRODUCT: 'product', SERVICE: 'service' });

export const CATALOG_STATUS = Object.freeze({
  DRAFT: 'draft',
  PLANNED: 'planned',
  AVAILABLE: 'available',
  RETIRED: 'retired',
});

// Pure: is this record purchasable under Phase 3A rules? Drafts + non-available + checkout-ineligible = no.
export function isPurchasable(record) {
  if (!record) return false;
  if (record.status !== CATALOG_STATUS.AVAILABLE) return false;
  if (record.checkoutEligible !== true) return false;
  return true;
}

// -------- Product factory --------
export function createProduct(input = {}) {
  return {
    kind: CATALOG_KIND.PRODUCT,
    id: input.id ?? '',
    name: input.name ?? '',
    description: input.description ?? '',
    priceLabel: input.priceLabel ?? '', // display string only; no numeric inference
    status: input.status ?? CATALOG_STATUS.DRAFT,
    checkoutEligible: input.checkoutEligible ?? false,
    source: input.source ?? 'unknown',
    provenance: input.provenance ?? '',
    url: input.url ?? null, // intentionally null unless Loki supplies a real URL (do NOT invent)
  };
}

// -------- Service factory --------
export function createService(input = {}) {
  return {
    kind: CATALOG_KIND.SERVICE,
    id: input.id ?? '',
    name: input.name ?? '',
    description: input.description ?? '',
    priceLabel: input.priceLabel ?? '',
    time: input.time ?? '',
    deliverable: input.deliverable ?? '',
    idealFor: input.idealFor ?? '',
    status: input.status ?? CATALOG_STATUS.AVAILABLE,
    archetypeRefs: Array.isArray(input.archetypeRefs) ? input.archetypeRefs : [],
    source: input.source ?? 'unknown',
    provenance: input.provenance ?? '',
  };
}

// -------- Validators (pure, never throw) --------
const STATUS_VALUES = Object.values(CATALOG_STATUS);

export function validateCatalogRecord(r) {
  const errors = [];
  if (!r || typeof r !== 'object') return { valid: false, errors: ['record must be an object'] };
  if (![CATALOG_KIND.PRODUCT, CATALOG_KIND.SERVICE].includes(r.kind)) errors.push('record.kind must be product|service');
  if (!r.id) errors.push('record.id is required (stable ID)');
  else if (!/^[a-z0-9][a-z0-9-]*$/.test(r.id)) errors.push(`record.id "${r.id}" must be a stable slug (lowercase, digits, hyphens)`);
  if (!r.name) errors.push('record.name is required');
  if (!STATUS_VALUES.includes(r.status)) errors.push(`record.status "${r.status}" must be ${STATUS_VALUES.join('|')}`);
  if (r.kind === CATALOG_KIND.PRODUCT) {
    if (r.checkoutEligible === true && r.status !== CATALOG_STATUS.AVAILABLE) {
      errors.push('product.checkoutEligible=true requires status=available');
    }
    if (r.url && typeof r.url !== 'string') errors.push('product.url must be null or a string');
  }
  if (r.kind === CATALOG_KIND.SERVICE) {
    if (!Array.isArray(r.archetypeRefs)) errors.push('service.archetypeRefs must be an array');
  }
  return { valid: errors.length === 0, errors };
}

// Structural archetype-reference check: every service.archetypeRefs entry must exist in knownArchetypeIds.
export function validateArchetypeReferences(records, knownArchetypeIds = []) {
  const errors = [];
  const known = new Set(knownArchetypeIds);
  for (const r of records) {
    if (r.kind !== CATALOG_KIND.SERVICE) continue;
    for (const ref of r.archetypeRefs || []) {
      if (!known.has(ref)) errors.push(`service ${r.id} references unknown archetype "${ref}"`);
    }
  }
  return { valid: errors.length === 0, errors };
}

// Whole-catalog validation: each record + draft non-purchasable invariant + archetype refs.
export function validateCatalog(records, knownArchetypeIds = []) {
  const errors = [];
  const ids = new Set();
  for (const r of records) {
    if (ids.has(r.id)) errors.push(`duplicate catalog id "${r.id}"`);
    ids.add(r.id);
    const v = validateCatalogRecord(r);
    if (!v.valid) errors.push(...v.errors.map((e) => `${r.id}: ${e}`));
    // Draft invariant: drafts must never be purchasable.
    if (r.status === CATALOG_STATUS.DRAFT && isPurchasable(r)) {
      errors.push(`${r.id}: draft must not be purchasable`);
    }
  }
  const ar = validateArchetypeReferences(records, knownArchetypeIds);
  if (!ar.valid) errors.push(...ar.errors);
  return { valid: errors.length === 0, errors };
}
