import React, { useState } from 'react';
import { useRoute } from './shell/useRoute.js';
import { ROUTES } from './shell/routes.js';
import ErrorBoundary from './shell/ErrorBoundary.jsx';
import Nav from './shell/Nav.jsx';
import Footer from './shell/Footer.jsx';
import { GAMES, GAME_LIST } from './games/registry.js';
import { diagnostics } from './data/scans.js';
import { archetypes, productLadder } from './data/archetypes.js';
import { gumroadProducts, FUNNEL_HOOK } from './data/products.js';
import { services, products } from './catalog/index.js';
import ReflectionExperience from './ReflectionExperience.jsx';
import './shell/styles.css';

// PHASE 1B SHELL (restyled for private preview). Hash-backed routes; ErrorBoundary wraps every route.
// All six games migrated (Ratatoskr = observable-only, unresolved). No scoring/product behavior changed.
// Naming convention preserved (lm-* classes) so the existing test contract is unaffected.
const ACTIVE_BY_ROUTE = {
  games: 'play', diagnostics: 'diagnose', reflection: 'reflect', services: 'services', products: 'products',
};

export default function App({ gameScoring } = {}) {
  const { route, navigate } = useRoute();
  const [lastResult, setLastResult] = useState(null);
  const onResult = (r) => setLastResult(r);
  const onGameExit = () => navigate(ROUTES.GAMES);

  const game = route.name === 'game' ? GAMES[route.params.id] : null;
  const activeId = ACTIVE_BY_ROUTE[route.name];

  return (
    <>
      {/* PRIVATE PREVIEW ONLY — prototype label. No production/domain/public scope. Working-tree change only. */}
      <div className="lm-preview-banner" role="note">
        <strong>Closed Portal · Reflection Prototype</strong> — the full Mischief Scan and live offers aren't open yet. Five reflection prompts are here to try; your words stay on this device. No checkout, no accounts.
      </div>
      <Nav navigate={navigate} activeId={activeId} />
      <ErrorBoundary>
        <main className="lm-main">
          {route.name === 'home' && (
            <>
              <section className="lm-hero">
                <p className="section-eyebrow">God-Level Ops · Norse Mischief Diagnostics</p>
                <h1 className="lm-display">Run the mischief.<br />Find what's eating your business.</h1>
                <p className="lead">A playable diagnostic world where Norse archetypes expose the bottlenecks, blind spots, and wolves at the door — then hand you the fix.</p>
                <div className="lm-hero-cta">
                  <button className="lm-btn" onClick={() => navigate(ROUTES.GAMES)}>Play the Games</button>
                  <button className="lm-btn lm-btn--ghost" onClick={() => navigate(ROUTES.REFLECTION)}>Begin a Reflection</button>
                </div>
                {lastResult && (
                  <div className="lm-lastresult" data-testid="last-result">
                    Last result: {lastResult.gameId} = {lastResult.score} ({lastResult.status})
                  </div>
                )}
              </section>

              <div className="divider-rune">ᛟ ᛉ ᛊ</div>

              <section className="section-head">
                <p className="section-eyebrow">Enter the realms</p>
                <h2>Choose your mischief</h2>
                <div className="lm-grid">
                  <button className="lm-card" onClick={() => navigate(ROUTES.GAMES)}>
                    <span className="lm-eyebrow">Arcade</span><h3>Enter the Arcade</h3>
                    <p>Six Norse trials that surface how your team actually operates.</p>
                  </button>
                  <button className="lm-card" onClick={() => navigate(ROUTES.DIAGNOSTICS)}>
                    <span className="lm-eyebrow">Diagnostics</span><h3>Run a Diagnostic</h3>
                    <p>Guided scans that map the mischief to a plan.</p>
                  </button>
                  <button className="lm-card" onClick={() => navigate(ROUTES.SERVICES)}>
                    <span className="lm-eyebrow">Engagements</span><h3>Services</h3>
                    <p>God-level fixes delivered by the archetypes themselves.</p>
                  </button>
                </div>
              </section>
            </>
          )}

          {route.name === 'games' && (
            <>
              <section className="section-head">
                <p className="section-eyebrow">The Arcade</p>
                <h2>Play the games</h2>
                <p className="lead">Each game is a lens. The lessons feed your reflection — no scoring, no verdict.</p>
              </section>
              <div className="lm-grid">
                {GAME_LIST.map((g) => (
                  <button key={g.id} className="lm-card" disabled={!g.migrated}
                    onClick={() => g.migrated && navigate(ROUTES.GAME(g.id))}>
                    <span className="lm-eyebrow">{g.unresolved ? 'Unresolved' : 'Playable'}</span>
                    <h3>{g.name}{g.unresolved ? ' ⚠' : ''}</h3>
                    <p>{g.lesson}</p>
                    <span className="lm-note">{g.unresolved ? 'observable-only (unresolved)' : g.migrated ? 'Enter →' : 'staged'}</span>
                  </button>
                ))}
              </div>
            </>
          )}

          {route.name === 'game' && game && (
            <>
              {game.unresolved && <p className="lm-flag">spec-status: unresolved — observable behavior only, no invented mechanics.</p>}
              <game.Component onResult={onResult} onExit={onGameExit} scoring={gameScoring} />
            </>
          )}

          {route.name === 'game' && !game && (
            <>
              <button className="lm-back" onClick={onGameExit}>← Games</button>
              <p className="lm-note">“{route.params.id}” is unknown.</p>
            </>
          )}

          {route.name === 'diagnostics' && (
            <>
              <section className="section-head">
                <p className="section-eyebrow">Diagnostics</p>
                <h2>Run a diagnostic</h2>
                <p className="lead">Pick a realm to begin mapping the mischief.</p>
              </section>
              <div className="lm-grid">
                {diagnostics.map((d) => (
                  <button key={d.id} className="lm-card" onClick={() => navigate(ROUTES.SURVEY(d.id))}>
                    <span className="lm-eyebrow">Scan</span>
                    <h3>{d.title}</h3><p>{d.promise}</p>
                    <span className="lm-note">{d.time} · {d.audience} · {d.qs} qs</span>
                  </button>
                ))}
              </div>
            </>
          )}

          {route.name === 'survey' && (
            <>
              <button className="lm-back" onClick={() => navigate(ROUTES.DIAGNOSTICS)}>← Diagnostics</button>
              <h1>{diagnostics.find((d) => d.id === route.params.id)?.title || 'Survey'}</h1>
              <p className="lm-note">Recovered preview only — full 25/30 questions are a CONTENT GAP (see docs/scan-content-provenance.md).</p>
            </>
          )}

          {route.name === 'reflection' && (
            <ReflectionExperience navigate={navigate} />
          )}

          {route.name === 'services' && (
            <>
              <section className="section-head">
                <p className="section-eyebrow">Engagements</p>
                <h2>Services</h2>
                <p className="lead">Paid engagements led by the archetypes. No reflection result determines these — a standalone catalog.</p>
              </section>
              <div className="lm-grid">
                {services.map((s) => (
                  <div key={s.id} className="lm-card">
                    <span className="lm-eyebrow">{s.archetypeRefs?.[0] || 'engagement'}</span>
                    <h3>{s.name}</h3><span className="lm-price">{s.priceLabel}</span>
                    <p>{s.description}</p>
                    <span className="lm-note">{s.time} · {s.idealFor}</span>
                  </div>
                ))}
              </div>
            </>
          )}

          {route.name === 'products' && (
            <>
              <section className="section-head">
                <p className="section-eyebrow">Product Vault</p>
                <h2>The ladder</h2>
                <p className="lead">From free mischief to done-for-you. Drafts below are not yet purchasable.</p>
              </section>
              <div className="lm-ladder">{productLadder.map((p) => (
                <div key={p.t} className="lm-card"><span className="lm-eyebrow">Tier</span><h3>{p.t}</h3><span className="lm-price">{p.p}</span><p>{p.d}</p></div>))}</div>
              <h2>Drafts (non-purchasable)</h2>
              <ul>{products.map((g) => (
                <li key={g.id}>{g.name} — status={g.status}, checkoutEligible={String(g.checkoutEligible)}{g.url ? `, url=${g.url}` : ', url=none (not invented)'}</li>
              ))}</ul>
              <p className="lm-note">Funnel: {FUNNEL_HOOK.steps.join(' → ')} (Gumroad not wired: drafts non-purchasable; no product URLs invented).</p>
            </>
          )}

          {route.name === 'directory' && (
            <>
              <h1>God-Level Business Directory</h1>
              <p className="lm-note">Exclusive directory — verified = active client. (Reference shell; no data recovered in Phase 0B.)</p>
            </>
          )}

          {route.name === 'blog' && (
            <>
              <h1>Mischief Letters</h1>
              <p className="lm-note">Blog reference shell. (Content served by live site; not recovered in Phase 0B.)</p>
            </>
          )}
        </main>
      </ErrorBoundary>
      <Footer />
    </>
  );
}
