import React, { useEffect, useRef, useState, useImperativeHandle, forwardRef } from 'react';
import * as ratatoskrScoring from '../scoring/ratatoskr.js';
import { makeResult, RESULT_STATUS } from '../shell/contract.js';
import GameChrome from './GameChrome.jsx';

// Ratatoskr — OBSERVABLE-ONLY candidate (Phase 3 juice: presentation only).
// spec-status: unresolved — NO missing mechanics invented, NOT represented as production-ready.
// Only OBSERVABLE behavior preserved (score state, reset, +25 "Play Action" from the artifact shell).
const Ratatoskr = forwardRef(function Ratatoskr({ onResult, onExit, scoring = ratatoskrScoring }, ref) {
  const { RATATOSKR_SPEC_STATUS, RATATOSKR_OBSERVED, ratatoskrPlayAction } = scoring;
  const [phase, setPhase] = useState('idle');
  const [score, setScore] = useState(0);
  const [paused, setPaused] = useState(false);
  const cleanupRef = useRef(false);

  const start = () => setPhase('running');
  const reset = () => { setPhase('idle'); setScore(0); };
  // Observable artifact behavior only — NOT a design-bible scoring formula.
  const play = () => { if (phase !== 'running' || paused) return; setScore((s) => ratatoskrPlayAction(s)); };
  const finish = () => {
    setPhase('done');
    onResult?.(makeResult({
      gameId: 'ratatoskr', score, status: RESULT_STATUS.INCOMPLETE,
      meta: { unresolved: true, specStatus: RATATOSKR_SPEC_STATUS, observedIncrement: RATATOSKR_OBSERVED.playActionIncrement },
    }));
  };

  useEffect(() => {
    const onVis = () => setPaused(document.hidden);
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);
  useEffect(() => () => { cleanupRef.current = true; }, []);
  useImperativeHandle(ref, () => ({ pause: () => setPaused(true), resume: () => setPaused(false), restart: reset, exit: () => onExit?.(), isCleanedUp: () => cleanupRef.current }), [onExit]);

  const verdict = phase === 'done' ? {
    tone: 'neutral', label: 'The Messenger Returns', lines: [
      `Observed score: ${score}`,
      'Mechanics UNRESOLVED — not a final verdict.',
      'See docs/ratatoskr-spec-gap.md.',
    ],
  } : null;

  return (
    <GameChrome
      title="Ratatoskr"
      lesson={RATATOSKR_OBSERVED.theme}
      accent="ratatoskr"
      unresolved
      hud={`Score ${score} · Phase: ${phase}`}
      paused={paused}
      verdict={verdict}
      phase={phase}
      actions={phase === 'done' ? (
        <>
          <button className="lm-btn" onClick={reset}>Restart</button>
          <button className="lm-btn" onClick={() => onExit?.()}>Exit</button>
        </>
      ) : null}
    >
      <h3 className="lm-flag">spec-status: {RATATOSKR_SPEC_STATUS}</h3>
      <p className="lm-note">Observable-only candidate. Mechanics UNRESOLVED — no formula, window, or win condition invented. See docs/ratatoskr-spec-gap.md.</p>
      {phase === 'idle' && <button className="lm-btn" onClick={start}>Start</button>}
      {phase === 'running' && (
        <>
          <button className="lm-btn" onClick={play} disabled={paused}>+ Play Action (observed +{RATATOSKR_OBSERVED.playActionIncrement})</button>
          <button className="lm-btn" onClick={finish}>Finish</button>
        </>
      )}
    </GameChrome>
  );
});

export default Ratatoskr;
