import React, { useEffect, useRef, useState, useImperativeHandle, forwardRef } from 'react';
import * as fenrirScoring from '../scoring/fenrir.js';
import { makeResult, RESULT_STATUS } from '../shell/contract.js';
import GameChrome from './GameChrome.jsx';

// REFERENCE GAME (Phase 3 juice). All scoring/state logic UNCHANGED — only presentation wrapped in
// GameChrome with themed meters + a verdict screen. Contract: mount→start→play→result→restart→exit→cleanup.
const Fenrir = forwardRef(function Fenrir({ onResult, onExit, scoring = fenrirScoring }, ref) {
  const { FENRIR_CHAINS, FENRIR_CONFIG, scoreStrike, timeBonus, fenrirRank } = scoring;
  const [phase, setPhase] = useState('idle');
  const [score, setScore] = useState(0);
  const [chain, setChain] = useState(0);
  const [integrity, setIntegrity] = useState(100);
  const [perfects, setPerfects] = useState(0);
  const [hits, setHits] = useState(0);
  const [log, setLog] = useState([]);
  const [paused, setPaused] = useState(false);
  const [flash, setFlash] = useState(false);
  const timerRef = useRef(null);
  const cleanupRef = useRef(false);

  const start = () => { setPhase('running'); };
  const reset = () => {
    setPhase('idle'); setScore(0); setChain(0); setIntegrity(100);
    setPerfects(0); setHits(0); setLog([]); cleanupRef.current = false;
  };
  const finish = () => {
    setPhase('done');
    const rank = fenrirRank({ score, perfects, hits });
    const status = integrity <= 0 ? RESULT_STATUS.LOSE
      : (rank === 'GLEIPNIR_UNBOUND' ? RESULT_STATUS.WIN : RESULT_STATUS.INCOMPLETE);
    onResult?.(makeResult({ gameId: 'fenrir', score, status, meta: { rank, perfects, hits, integrity: Math.round(integrity) } }));
  };

  const strike = () => {
    if (phase !== 'running' || paused) return;
    const x = Math.random() * 2 - 1;
    const r = scoreStrike(x, chain, integrity);
    const newIntegrity = Math.max(0, Math.min(100, integrity + r.integrityDelta));
    setScore((s) => s + r.points + (r.hit ? timeBonus(FENRIR_CONFIG.TIME_LIMIT) : 0));
    setIntegrity(newIntegrity);
    setChain((c) => (r.hit && r.perfect ? c + 1 : c));
    if (r.perfect) setPerfects((p) => p + 1);
    if (r.hit) setHits((h) => h + 1);
    setLog((l) => [`${r.perfect ? 'PERFECT' : r.hit ? 'hit' : 'miss'} (+${r.points})`, ...l].slice(0, 5));
    setFlash(true); setTimeout(() => setFlash(false), 500);
    if (newIntegrity <= 0) finish();
  };

  useEffect(() => {
    const onVis = () => { if (document.hidden) setPaused(true); else setPaused(false); };
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);
  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); cleanupRef.current = true; }, []);
  useImperativeHandle(ref, () => ({
    pause: () => setPaused(true), resume: () => setPaused(false),
    restart: reset, exit: () => onExit?.(), isCleanedUp: () => cleanupRef.current,
  }), [onExit]);

  const rank = fenrirRank({ score, perfects, hits });
  const verdict = phase === 'done' ? (() => {
    const tone = integrity <= 0 ? 'lose' : (rank === 'GLEIPNIR_UNBOUND' ? 'win' : 'neutral');
    const label = integrity <= 0 ? 'The Wolf Breaks Free' : (rank === 'GLEIPNIR_UNBOUND' ? 'Gleipnir Unbound' : 'The Chain Holds… Barely');
    return { tone, label, lines: [
      `Score: ${score}`,
      `Chain reached: ${FENRIR_CHAINS[chain]?.name ?? 'LÆDING'}`,
      `Integrity: ${Math.round(integrity)}% · Perfects: ${perfects}`,
      rank === 'GLEIPNIR_UNBOUND' ? 'Your guard-rails held. The wolf stays bound.' : 'Tighten the rails before the next bite.',
    ] };
  })() : null;

  return (
    <GameChrome
      title="Fenrir — Chain Strike"
      lesson="Guard-rails, validation, compliance. Your SOPs are Gleipnir — invisible, light, unbreakable."
      accent="fenrir"
      hud={`Score ${score} · Chain ${FENRIR_CHAINS[chain]?.name ?? 'LÆDING'} · Phase: ${phase}`}
      paused={paused}
      verdict={verdict}
      phase={phase}
      actions={phase === 'done' ? (
        <>
          <button className="lm-btn" onClick={reset}>Restart</button>
          <button className="lm-btn" onClick={() => onExit?.()}>Exit</button>
        </>
      ) : null}
    >
      <div className={`lm-meter ${integrity <= 35 ? 'lm-meter--danger' : 'lm-meter--good'}`} data-testid="integrity-meter">
        <i style={{ width: `${integrity}%` }} />
      </div>
      <div className="lm-chain-row">
        {FENRIR_CHAINS.map((c, i) => (
          <span key={c.name} className={`lm-chain-node ${i === chain ? 'lm-chain-node--active' : ''}`}>{c.name}</span>
        ))}
      </div>
      {phase === 'idle' && <button className="lm-btn" onClick={start}>Start</button>}
      {phase === 'running' && (
        <button className={`lm-btn ${flash ? 'lm-flash' : ''}`} onClick={strike} disabled={paused} data-testid="strike-btn">
          + Strike {paused ? '(paused)' : ''}
        </button>
      )}
      <ul className="lm-log">{log.map((e, i) => <li key={i}>{e}</li>)}</ul>
      <p className="lm-note">Spec: design bible §01. Reference game for Phase 1A lifecycle contract.</p>
    </GameChrome>
  );
});

export default Fenrir;
