// Phase 3A — Canonical catalog built from existing recovered sources (no invention).
//
// Services  <- data/archetypes.js (14 paid personas). Each persona IS an archetype, so archetypeRefs
//             points to its own id (structural self-reference, validated against the archetype catalog).
// Products  <- data/products.js gumroadProducts (3 DRAFTS). Status preserved as draft, checkoutEligible
//             false (Phase 0B rule). No URLs invented (url: null).
//
// The product ladder (data/archetypes.js productLadder) is a TIERING summary, not a record list; it is
// exported separately for display and is NOT treated as purchasable items.

import { archetypes, productLadder } from '../data/archetypes.js';
import { gumroadProducts } from '../data/products.js';
import {
  createService, createProduct, CATALOG_STATUS, validateCatalog, isPurchasable,
} from './catalog.js';

// Services: each archetype persona -> a service record. archetypeRefs = [self.id] (structural).
export const services = archetypes.map((a) => createService({
  id: a.id, // stable slug id, matches archetype id
  name: a.name,
  description: a.desc,
  priceLabel: a.price,
  time: a.time,
  deliverable: a.deliverable,
  idealFor: a.ideal,
  status: CATALOG_STATUS.AVAILABLE,
  archetypeRefs: [a.id],
  source: 'arcade-content.json:archetypes',
  provenance: 'owner-recovered canonical',
}));

// Products: the 3 Gumroad drafts. Drafts stay non-purchasable. No URL invented.
export const products = gumroadProducts.map((g) => createProduct({
  id: g.id,
  name: g.name,
  description: '',
  priceLabel: '',
  status: g.status || CATALOG_STATUS.DRAFT,
  checkoutEligible: g.checkoutEligible ?? false,
  source: 'gumroad-lokis-products.json',
  provenance: '3 DRAFT products, published=false (prior session)',
  url: null,
}));

// Unified catalog (products + services) for validation + render.
export const catalog = [...products, ...services];

// Known archetype IDs (for structural reference validation).
export const archetypeIds = archetypes.map((a) => a.id);

// Validate at module load (pure; surfaces structural problems immediately in tests).
export const catalogValidation = validateCatalog(catalog, archetypeIds);

// Convenience: nothing in the catalog is purchasable today (drafts + no available/checkout-eligible).
export const purchasableCount = catalog.filter(isPurchasable).length;

export { productLadder, isPurchasable, validateCatalog };
