// Phase 2C — Reflection persistence (resume). Extends the existing PersistenceAdapter contract with
// reflection-specific key helpers. Persistence is LOCAL ONLY (localStorageAdapter) — no backend, no
// network, no server. A user can start, leave, and resume their reflection.
//
// NON-OBVIOUS LOGIC:
// - Key convention mirrors design-bible §00 style: loki_reflection_<playerId>.
// - We store ONLY answers + a createdAt + an in-progress flag; no score/archetype (reflection mode).
// - saveReflection merges with any existing saved draft (resume), preserving earlier prompt answers.
// - loadReflection returns null when nothing saved (clean start).
// - All access is try/catch wrapped (adapter is tolerant); a broken/missing storage never throws.

import { PersistenceAdapter, BEST_SCORE_KEY } from './adapter.js';
import { LocalStorageAdapter, persistence } from './localStorageAdapter.js';

export const REFLECTION_KEY = (playerId = 'anonymous') => `loki_reflection_${playerId}`;

// Pure helpers (operate on the adapter instance passed in, default = local adapter).
export function saveReflectionDraft(adapter = persistence, playerId = 'anonymous', draft = {}) {
  const key = REFLECTION_KEY(playerId);
  const prev = loadReflectionDraft(adapter, playerId);
  const merged = {
    playerId,
    createdAt: prev?.createdAt || draft.createdAt || null,
    answers: mergeAnswers(prev?.answers || [], draft.answers || []),
    updatedAt: null,
  };
  try { adapter.set(key, JSON.stringify(merged)); } catch { /* noop */ }
  return merged;
}

export function loadReflectionDraft(adapter = persistence, playerId = 'anonymous') {
  try {
    const raw = adapter.get(REFLECTION_KEY(playerId));
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.answers)) return null;
    return parsed;
  } catch { return null; }
}

export function clearReflectionDraft(adapter = persistence, playerId = 'anonymous') {
  try { adapter.remove(REFLECTION_KEY(playerId)); } catch { /* noop */ }
  return true;
}

export function hasReflectionDraft(adapter = persistence, playerId = 'anonymous') {
  return loadReflectionDraft(adapter, playerId) !== null;
}

// Pure: latest non-empty answer per promptId wins (resume semantics).
function mergeAnswers(prev = [], next = []) {
  const byId = new Map();
  for (const a of prev) if (a && a.promptId) byId.set(a.promptId, a);
  for (const a of next) if (a && a.promptId) byId.set(a.promptId, a); // overwrite
  return Array.from(byId.values());
}

export { PersistenceAdapter, LocalStorageAdapter, persistence, BEST_SCORE_KEY };
