// Phase 2C — Pure reflection engine (Path B: reflection-only, no scoring/inference).
//
// PURPOSE: Turn free-text answers + optional game results into a STRUCTURED, resumable reflection
// record — NOT an archetype profile. No weights, no thresholds, no confidence, no product offers.
//
// NON-OBVIOUS LOGIC:
// - A reflection is "complete" when every REFLECTION_PROMPT has a non-empty answer (skips/blanks count).
// - Game context is INCLUDED but explicitly NOT scored: `gameContext` carries the registry lesson + an
//   `unresolved` flag; it is descriptive metadata, never an axis input.
// - Ratatoskr is EXCLUDED from scan context (engagement-only, approved). Its engagement metadata is
//   recorded separately and never reaches `gameContext`.
// - `futureScoring` is a deliberately EMPTY placeholder documenting the integration point: when Loki
//   supplies the Path A model, the SAME reflection record + game context feed the versioned
//   runApprovedModel (archetypeModelVersion bump), with zero UI changes here.
// - `confidence` is ALWAYS 'none' in a reflection record. We never emit a fake confidence score.

import { createPersistenceRecord } from './schemas.js';
import { modelVersions } from './version.js';
import { REFLECTION_PROMPTS, REFLECTION_EXPERIENCE, totalReflectionPrompts } from './reflectionContent.js';
import { excludeRatatoskrFromScanContext, RATATOSKR_PRODUCT_DECISION } from './ratatoskrDecision.js';

// Pure: one reflection answer.
export function createReflectionAnswer(input = {}) {
  return {
    promptId: input.promptId ?? '',
    text: input.text ?? '',
    answeredAt: input.answeredAt ?? null,
  };
}

export function validateReflectionAnswer(a) {
  const errors = [];
  if (!a || typeof a !== 'object') return { valid: false, errors: ['reflectionAnswer must be an object'] };
  if (!a.promptId) errors.push('reflectionAnswer.promptId required');
  if (typeof a.text !== 'string') errors.push('reflectionAnswer.text must be a string');
  return { valid: errors.length === 0, errors };
}

// Pure: completion ratio 0..1 over the required prompts.
export function reflectionCompletion(answers = []) {
  const total = totalReflectionPrompts();
  const answered = new Set(answers.filter((a) => a && a.text && a.text.trim().length > 0).map((a) => a.promptId));
  const done = REFLECTION_PROMPTS.filter((p) => answered.has(p.id)).length;
  return { answered: done, total, ratio: total ? Math.round((done / total) * 1000) / 1000 : 0, complete: done === total };
}

// Pure: build a reflection record from answers + game results (game results = context only).
export function buildReflection({ answers = [], gameResults = [], recordId = '', playerId = 'anonymous', createdAt = null } = {}) {
  const errors = [];
  for (const a of answers) { const v = validateReflectionAnswer(a); if (!v.valid) errors.push(...v.errors); }

  // Ratatoskr is engagement-only -> excluded from scan context (approved product decision).
  const scanContext = excludeRatatoskrFromScanContext(gameResults);

  const completion = reflectionCompletion(answers);
  const versions = modelVersions(); // archetypeModelVersion stays 0.0.0 — reflection only

  // Descriptive game context (NOT scored). Maps registry lessons to answered prompts by theme.
  const gameContext = scanContext.map((g) => {
    const card = REFLECTION_EXPERIENCE.gameContext.find((c) => c.gameId === g.gameId);
    return {
      gameId: g.gameId,
      lesson: card ? card.lesson : '',
      unresolved: card ? card.unresolved : false,
      note: 'context only — not scored in the reflection experience',
    };
  });

  const record = createPersistenceRecord({
    recordId, playerId,
    scanId: REFLECTION_EXPERIENCE.id,
    answers: answers.map((a) => ({ questionId: a.promptId, scanId: REFLECTION_EXPERIENCE.id, optionId: null, value: a.text, answeredAt: a.answeredAt, valid: false })),
    gameSignals: scanContext, // Ratatoskr removed; engagement stored separately
    scoreBreakdown: null, // explicit: no score in reflection mode
    archetypeResults: [], // explicit: no archetype in reflection mode
    createdAt,
    completedAt: completion.complete ? (createdAt || null) : null,
    modelVersions: versions,
    schemaVersion: versions.schemaVersion,
  });

  return {
    experienceId: REFLECTION_EXPERIENCE.id,
    title: REFLECTION_EXPERIENCE.title,
    completion,
    confidence: 'none', // ALWAYS none — reflection makes no archetype claim
    answers,
    gameContext, // descriptive, unsorted
    ratatoskr: RATATOSKR_PRODUCT_DECISION, // echoes the approved decision for transparency
    futureScoring: {
      // INTEGRATION POINT (empty until Path A model supplied):
      // the same `answers` + `scanContext` feed runApprovedModel once archetypeModelVersion > 0.0.0.
      enabled: false,
      reason: 'reflection-only mode; archetype model not authorized (Phase 2C)',
    },
    record,
    errors,
  };
}

// Pure: the experience contract for the UI (prompts + context + explanation copy).
export function reflectionExperienceContract() {
  return {
    ...REFLECTION_EXPERIENCE,
    total: totalReflectionPrompts(),
    explanation: 'This is a reflection experience, not a diagnostic. Your answers are not scored, ' +
      'no archetype is assigned, and no confidence score is shown. Game results appear as context only. ' +
      'When a validated scoring model becomes available, the same answers can later produce an archetype profile.',
  };
}
