// Sleipnir — Eight-Leg Sprint scoring (design bible §04). VERBATIM, behavior unchanged.
export const SLEIPNIR_CONFIG = {
  START_SPEED: 6,
  SPEED_STEP: 0.02, // +2% per 10s
  SPEED_STEP_EVERY: 10, // seconds
  MAX_SPEED: 14,
  MAGNET_EVERY: 30, // seconds
  MAGNET_DURATION: 4,
  MULTIPLIER: { base: 1, parallel: 1.5, magnetParallel: 2 },
};

// Distance-based score: floor(dist*1.2 + coins*10*multi).
export function sleipnirScore(dist, coins, multiplierKey = 'base') {
  const multi = SLEIPNIR_CONFIG.MULTIPLIER[multiplierKey] ?? 1;
  return Math.floor(dist * 1.2 + coins * 10 * multi);
}

// Speed ramp: starts 6, +2% per 10s, cap 14.
export function sleipnirSpeed(elapsedSec) {
  const steps = Math.floor(elapsedSec / SLEIPNIR_CONFIG.SPEED_STEP_EVERY);
  const s = SLEIPNIR_CONFIG.START_SPEED * Math.pow(1 + SLEIPNIR_CONFIG.SPEED_STEP, steps);
  return Math.min(SLEIPNIR_CONFIG.MAX_SPEED, s);
}
