// Shared lifecycle + result contract (Phase 1A). Every game MUST implement this contract so the
// shell can drive mount / pause / restart / complete / exit uniformly. Reference impl: Fenrir.
//
// Game component props:
//   onResult(result: GameResult)  — called once on completion
//   onExit()                      — called when the player leaves (shell-bound; UI may also call)
// Game component must expose (via ref or internal effect) optional lifecycle callbacks:
//   pause()  / resume()           — for visibilitychange handling (best-effort)
//   restart()                     — reset to initial state
//   cleanup()                     — release timers/listeners on unmount
//
// GameResult shape (canonical):
export const RESULT_STATUS = { WIN: 'win', LOSE: 'lose', INCOMPLETE: 'incomplete' };

export function makeResult({ gameId, score, status = RESULT_STATUS.INCOMPLETE, meta = {} }) {
  return {
    gameId,
    score: Number(score) || 0,
    status,
    playedAt: new Date().toISOString(),
    meta, // game-specific extras (level, accuracy, rank, etc.)
  };
}

// Lifecycle event names emitted to a registered listener (for tests + debugging).
export const LIFECYCLE = {
  MOUNT: 'mount', START: 'start', PAUSE: 'pause', RESUME: 'resume',
  RESTART: 'restart', COMPLETE: 'complete', EXIT: 'exit', CLEANUP: 'cleanup',
};

// Minimal contract check used by the shell/error boundary to fail fast on bad games.
export function assertGameContract(props) {
  if (typeof props?.onResult !== 'function') {
    throw new Error('Game must receive onResult(result: GameResult)');
  }
}
