// Fenrir — Chain Strike scoring (design bible §01). VERBATIM formulas, behavior unchanged.
// Window = % of canvas width that counts as a "hit" sweet spot.
export const FENRIR_CHAINS = [
  { name: 'LÆDING', window: 0.40, speed: 1.0 },
  { name: 'DROMI', window: 0.20, speed: 1.4 },
  { name: 'GLEIPNIR', window: 0.12, speed: 1.8, drift: true },
];

export const FENRIR_CONFIG = {
  HIT_DMG: 100 / 3, // integrity lost per hit (3 clean hits break a chain)
  MISS_REFORM: 10, // % integrity regained on miss
  TIME_LIMIT: 90, // seconds
  PERFECT_BONUS: 50, // centre 40% of green
  TIME_BONUS_PER_SEC: 2,
  BASE_PER_HIT: 100,
  MAX_SCORE: 750,
};

// Score a single strike. x in [-1,1] is pendulum position (0 = dead centre).
// Returns { hit, perfect, points, integrityDelta }.
export function scoreStrike(x, chainIdx, integrity) {
  const chain = FENRIR_CHAINS[chainIdx] ?? FENRIR_CHAINS[0];
  const absX = Math.abs(x);
  const isHit = absX <= chain.window;
  const isPerfect = absX <= chain.window * 0.4; // centre 40% of green
  if (!isHit) {
    return { hit: false, perfect: false, points: 0, integrityDelta: +FENRIR_CONFIG.MISS_REFORM };
  }
  const points = FENRIR_CONFIG.BASE_PER_HIT + (isPerfect ? FENRIR_CONFIG.PERFECT_BONUS : 0);
  return { hit: true, perfect: isPerfect, points, integrityDelta: -FENRIR_CONFIG.HIT_DMG };
}

// Time bonus = remaining seconds * 2 (design bible §01).
export function timeBonus(remainingSec) {
  return Math.max(0, Math.round(remainingSec)) * FENRIR_CONFIG.TIME_BONUS_PER_SEC;
}

// Gleipnir Unbound badge: perfect run = all strikes perfect.
export function fenrirRank({ score, perfects, hits }) {
  if (hits > 0 && perfects === hits) return 'GLEIPNIR_UNBOUND';
  return score >= FENRIR_CONFIG.MAX_SCORE ? 'MAX' : 'NORMAL';
}
