import React, { useEffect, useRef, useState, useImperativeHandle, forwardRef } from 'react';
import { soulDeck, HEL_CONFIG } from '../data/soulDeck.js';
import * as helScoring from '../scoring/hel.js';
import { makeResult, RESULT_STATUS } from '../shell/contract.js';
import GameChrome from './GameChrome.jsx';

// Hel — Soul Sorting (Phase 3 juice). Scoring/state logic UNCHANGED; presentation via GameChrome.
const Hel = forwardRef(function Hel({ onResult, onExit, scoring = helScoring }, ref) {
  const { essenceDelta, soulInterval, helScore } = scoring;
  const [phase, setPhase] = useState('idle');
  const [queue, setQueue] = useState([]);
  const [essence, setEssence] = useState(0);
  const [correct, setCorrect] = useState(0);
  const [total, setTotal] = useState(0);
  const [wave, setWave] = useState(1);
  const [paused, setPaused] = useState(false);
  const timerRef = useRef(null);
  const cleanupRef = useRef(false);

  const spawn = () => {
    const s = soulDeck[Math.floor(Math.random() * soulDeck.length)];
    setQueue((q) => (q.length < 3 ? [...q, { ...s, id: Math.random() }] : q));
  };
  const decide = (soul, choice) => {
    const isCorrect = soul.correct === choice;
    setEssence((e) => e + essenceDelta(isCorrect));
    setCorrect((c) => c + (isCorrect ? 1 : 0));
    setTotal((t) => t + 1);
    setQueue((q) => q.filter((x) => x.id !== soul.id));
  };
  const start = () => {
    setPhase('running'); setWave(1); setQueue([]); setEssence(0); setCorrect(0); setTotal(0);
    spawn();
    timerRef.current = setInterval(() => { if (!paused) spawn(); }, soulInterval(1) * 1000);
  };
  const reset = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = null;
    setPhase('idle'); setQueue([]); setEssence(0); setCorrect(0); setTotal(0); setWave(1);
  };
  const finish = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    timerRef.current = null;
    setPhase('done');
    const res = helScore({ essence, correct, total });
    const status = res.rank === 'S' ? RESULT_STATUS.WIN : (total > 0 ? RESULT_STATUS.INCOMPLETE : RESULT_STATUS.LOSE);
    onResult?.(makeResult({ gameId: 'hel', score: res.score, status, meta: { accuracy: res.accuracy, rank: res.rank, essence } }));
  };

  useEffect(() => {
    const onKey = (e) => {
      if (phase !== 'running' || paused || queue.length === 0) return;
      if (e.key === 'a' || e.key === 'A') decide(queue[0], 'auto');
      if (e.key === 'd' || e.key === 'D') decide(queue[0], 'human');
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [phase, paused, queue]);
  useEffect(() => {
    const onVis = () => setPaused(document.hidden);
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);
  useEffect(() => () => { if (timerRef.current) clearInterval(timerRef.current); cleanupRef.current = true; }, []);
  useImperativeHandle(ref, () => ({ pause: () => setPaused(true), resume: () => setPaused(false), restart: reset, exit: () => onExit?.(), isCleanedUp: () => cleanupRef.current }), [onExit]);

  const res = helScore({ essence, correct, total });
  const verdict = phase === 'done' ? (() => {
    const tone = res.rank === 'S' ? 'win' : (total === 0 ? 'lose' : 'neutral');
    const label = res.rank === 'S' ? 'Hel\'s Balance Held' : (total === 0 ? 'The Gate Never Opened' : 'A Soul Slipped');
    return { tone, label, lines: [
      `Essence: ${essence}`,
      `Accuracy: ${(res.accuracy * 100).toFixed(0)}% (${correct}/${total})`,
      `Rank: ${res.rank}`,
      res.rank === 'S' ? '80% automate, 20% human — the dead sail smooth.' : 'Sort faster, or the wrong souls cross.',
    ] };
  })() : null;

  return (
    <GameChrome
      title="Hel — Soul Sorting"
      lesson="Triage, prioritisation, human-in-loop. 80% automate, 20% human = Hel's balance."
      accent="hel"
      hud={`Essence ${essence} · Acc ${(res.accuracy * 100).toFixed(0)}% · Rank ${res.rank} · Phase: ${phase}`}
      paused={paused}
      verdict={verdict}
      phase={phase}
      actions={phase === 'done' ? (
        <>
          <button className="lm-btn" onClick={reset}>Restart</button>
          <button className="lm-btn" onClick={() => onExit?.()}>Exit</button>
        </>
      ) : null}
    >
      <div className={`lm-meter lm-meter--good`} data-testid="essence-meter">
        <i style={{ width: `${Math.max(0, Math.min(100, essence))}%` }} />
      </div>
      {phase === 'idle' && <button className="lm-btn" onClick={start}>Start</button>}
      {phase === 'running' && (
        <div className="lm-deck">
          {queue.map((s) => (
            <div key={s.id} className="lm-soul">
              <span>{s.icon} {s.label}</span>
              <button className="lm-btn" onClick={() => decide(s, 'auto')} disabled={paused}>Automate (A)</button>
              <button className="lm-btn" onClick={() => decide(s, 'human')} disabled={paused}>Keep Human (D)</button>
              <span className="lm-soul-key">A / D</span>
            </div>
          ))}
          {queue.length === 0 && <span className="lm-note">Waiting for souls…</span>}
          <button className="lm-btn" onClick={finish}>Finish</button>
        </div>
      )}
      <p className="lm-note">Spec: design bible §03. {HEL_CONFIG.WAVES}×{HEL_CONFIG.PER_WAVE} souls; timers + A/D keys; cleanup verified.</p>
    </GameChrome>
  );
});

export default Hel;
