import React from 'react';
// Route-level error boundary (Phase 1A #6). Catches render/runtime errors in any route
// (incl. games) so a single broken game cannot white-screen the shell. Logs to console only
// (no network, no analytics). Falls back to a recoverable Home link.
export default class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }
  static getDerivedStateFromError(error) {
    return { error };
  }
  componentDidCatch(error, info) {
    // Local-only logging. No external reporting.
    console.error('[ErrorBoundary]', error, info?.componentStack);
  }
  reset = () => this.setState({ error: null });
  render() {
    if (this.state.error) {
      return (
        <div className="lm-error" role="alert">
          <h2>Something broke in this view.</h2>
          <p className="lm-note">{String(this.state.error?.message || this.state.error)}</p>
          <button className="lm-btn" onClick={() => { this.reset(); window.location.hash = '#/home'; }}>
            Return Home
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}
