// A localStorage adapter may be added later (see localStorageAdapter.js) but is NOT wired as
// a server. This file defines the contract every adapter must satisfy.
export class PersistenceAdapter {
  /** @returns {string|null} */
  get(key) { throw new Error('not implemented'); }
  /** @param {string} key @param {string} value */
  set(key, value) { throw new Error('not implemented'); }
  /** @param {string} key */
  remove(key) { throw new Error('not implemented'); }
}

