import React from 'react';
import { ROUTES } from './routes.js';
import BrandMark from './BrandMark.jsx';

// Top navigation shell. Links switch hash routes (real navigation: refresh/back/forward work).
// Active route is highlighted via the current hash.
const LINKS = [
  { id: 'play', label: 'Play', route: ROUTES.GAMES },
  { id: 'diagnose', label: 'Diagnose', route: ROUTES.DIAGNOSTICS },
  { id: 'reflect', label: 'Reflect', route: ROUTES.REFLECTION },
  { id: 'services', label: 'Services', route: ROUTES.SERVICES },
  { id: 'products', label: 'Vault', route: ROUTES.PRODUCTS },
];

export default function Nav({ navigate, activeId }) {
  return (
    <nav className="lm-nav">
      <a className="lm-brand" href="#/" onClick={() => navigate(ROUTES.HOME)}>
        <BrandMark />
        <span className="lm-brand-name">Loki's <b>Mischief</b></span>
      </a>
      {LINKS.map((l) => (
        <a
          key={l.id}
          href={`#${l.route.path}`}
          className={activeId === l.id ? 'active' : ''}
          onClick={() => navigate(l.route)}
        >
          {l.label}
        </a>
      ))}
    </nav>
  );
}
