// Jormungandr — Serpent Memory scoring (design bible §02). VERBATIM, behavior unchanged.
export const JORMUNGANDR_CONFIG = {
  NODES: ['ᚠ', 'ᚢ', 'ᚦ', 'ᚨ'], // Fehu, Uruz, Thurisaz, Ansuz
  TONES: [261.0, 329.0, 392.0, 440.0], // C-E-G-A Hz
  START_LENGTH: 3,
  SHOW_MS: 600,
  GAP_MS: 200,
  INPUT_TIMEOUT: 1.5, // seconds per press
  LIVES: 3,
  MAX_LEVEL: 12,
  HIT_AREA: 72, // px mobile
};

// Score = level*100 + streak^2 * 10. At level 12, streak contributes the bulk.
export function jormungandrScore(level, streak) {
  return level * 100 + streak * streak * 10;
}

// Dual-rune chords start at level 8+ (design bible §02).
export function usesChords(level) {
  return level >= 8;
}
