import { useCallback, useEffect, useState } from 'react';
import { parseHash } from './routes.js';

// Hash-backed route hook. Subscribes to hashchange so browser back/forward + refresh
// resolve to the correct view. Restores from location.hash on direct load (refresh test).
export function useRoute() {
  const [route, setRoute] = useState(() => parseHash());

  useEffect(() => {
    const onHash = () => setRoute(parseHash());
    window.addEventListener('hashchange', onHash);
    // Ensure a canonical hash exists on first load (so refresh is stable).
    if (!window.location.hash) window.location.replace('#/home');
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  const navigate = useCallback((to) => {
    const next = typeof to === 'string' ? to : (to.href || '#/home');
    window.location.hash = next;
    // Dispatch synchronously so listeners (and React state) update within the current act/tick,
    // rather than relying on the browser's async hashchange (which jsdom/timing can delay).
    window.dispatchEvent(new Event('hashchange'));
  }, []);

  const exit = useCallback(() => { window.location.hash = '#/games'; }, []);

  return { route, navigate, exit };
}
