import React, { useEffect, useRef, useState, useImperativeHandle, forwardRef } from 'react';
import * as jormScoring from '../scoring/jormungandr.js';
import { makeResult, RESULT_STATUS } from '../shell/contract.js';
import GameChrome from './GameChrome.jsx';

// Jormungandr — Serpent Memory (Phase 3 juice). Scoring/state UNCHANGED; themed nodes + life pips.
const Jormungandr = forwardRef(function Jormungandr({ onResult, onExit, scoring = jormScoring }, ref) {
  const { JORMUNGANDR_CONFIG: CFG, jormungandrScore, usesChords } = scoring;
  const [phase, setPhase] = useState('idle');
  const [level, setLevel] = useState(CFG.START_LENGTH);
  const [streak, setStreak] = useState(0);
  const [lives, setLives] = useState(CFG.LIVES);
  const [paused, setPaused] = useState(false);
  const [showing, setShowing] = useState(0);
  const timersRef = useRef([]);
  const cleanupRef = useRef(false);

  const clearTimers = () => { timersRef.current.forEach(clearTimeout); timersRef.current = []; };
  const loseLife = () => {
    setLives((l) => { const nl = l - 1; if (nl <= 0) finish(false); return nl; });
  };
  const finish = (won) => {
    clearTimers();
    setPhase('done');
    const status = won ? RESULT_STATUS.WIN : RESULT_STATUS.LOSE;
    onResult?.(makeResult({ gameId: 'jormungandr', score: jormungandrScore(level, streak), status, meta: { level, streak, lives } }));
  };
  const runShow = (idx = 0) => {
    if (phase !== 'running' || paused) return;
    if (idx >= level) { setShowing(-1); return; }
    setShowing(idx);
    const t1 = setTimeout(() => {
      setShowing(-1);
      const t2 = setTimeout(() => runShow(idx + 1), CFG.GAP_MS);
      timersRef.current.push(t2);
    }, CFG.SHOW_MS);
    timersRef.current.push(t1);
  };
  const start = () => {
    setPhase('running'); setLevel(CFG.START_LENGTH); setStreak(0); setLives(CFG.LIVES); setShowing(-1);
    runShow();
  };
  const reset = () => { clearTimers(); setPhase('idle'); setLevel(CFG.START_LENGTH); setStreak(0); setLives(CFG.LIVES); setShowing(-1); };
  const press = () => {
    if (phase !== 'running' || paused) return;
    setStreak((s) => s + 1);
    setLevel((l) => Math.min(CFG.MAX_LEVEL, l + 1));
  };

  useEffect(() => {
    if (phase !== 'running' || paused) return;
    const t = setTimeout(() => loseLife(), CFG.INPUT_TIMEOUT * 1000);
    timersRef.current.push(t);
    return () => clearTimeout(t);
  }, [phase, paused, streak]);
  useEffect(() => {
    const onVis = () => setPaused(document.hidden);
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);
  useEffect(() => () => { clearTimers(); cleanupRef.current = true; }, []);
  useImperativeHandle(ref, () => ({ pause: () => setPaused(true), resume: () => setPaused(false), restart: reset, exit: () => onExit?.(), isCleanedUp: () => cleanupRef.current }), [onExit]);

  const score = jormungandrScore(level, streak);
  const verdict = phase === 'done' ? (() => {
    const tone = lives > 0 ? 'win' : 'lose';
    return { tone, label: lives > 0 ? 'The Ouroboros Completes' : 'The Serpent Uncoils', lines: [
      `Level reached: ${level}`,
      `Streak: ${streak}`,
      `Lives: ${lives}`,
      lives > 0 ? 'Sequence held — the world stays wound.' : 'One link broke. Reroute and try again.',
    ] };
  })() : null;

  return (
    <GameChrome
      title="Jormungandr — Serpent Memory"
      lesson="Routing, sequencing, API order. Systems only work in order."
      accent="jormungandr"
      hud={`Level ${level} · Streak ${streak} · Lives ${lives} · Score ${score} · Chords ${usesChords(level) ? 'on' : 'off'} · Phase: ${phase}`}
      paused={paused}
      verdict={verdict}
      phase={phase}
      actions={phase === 'done' ? (
        <>
          <button className="lm-btn" onClick={reset}>Restart</button>
          <button className="lm-btn" onClick={() => onExit?.()}>Exit</button>
        </>
      ) : null}
    >
      <div className="lm-life-pips" data-testid="life-pips">
        {Array.from({ length: CFG.LIVES }).map((_, i) => (
          <span key={i} className={`lm-life-pip ${i >= lives ? 'lm-life-pip--lost' : ''}`} />
        ))}
      </div>
      {phase === 'idle' && <button className="lm-btn" onClick={start}>Start</button>}
      {phase === 'running' && (
        <div className="lm-nodes">
          {CFG.NODES.map((n, i) => (
            <span key={i} className="lm-node" data-lit={showing === i} onClick={() => press()}>{n}</span>
          ))}
          <button className="lm-btn" onClick={press} disabled={paused}>Press (repeat sequence)</button>
          <button className="lm-btn" onClick={() => finish(true)}>Finish</button>
        </div>
      )}
      <p className="lm-note">Spec: design bible §02. {CFG.LIVES} lives, max level {CFG.MAX_LEVEL}; show/gap timers + input timeout; cleanup verified.</p>
    </GameChrome>
  );
});

export default Jormungandr;
