// Phase 2A — Model versioning.
//
// PURPOSE: Four INDEPENDENT version axes so each layer of the scan/scoring/profile model can
// evolve without forcing a coordinated bump of the others. Every persisted scan record and every
// engine output embeds all four (see schemas.js + archetypeEngine.js) so any result is reproducible
// and auditable: re-running the same inputs + the same four versions MUST yield the same output.
//
// ASSUMPTIONS / NON-OBVIOUS LOGIC:
// - `schemaVersion`   = shape of the six entity schemas in schemas.js. Bumped only when a field is
//                       added/removed/retyped. Starts at 1.0.0 (this phase).
// - `questionSetVersion` = the SCAN QUESTION CONTENT. The full 25/30-question sets are a documented
//                       CONTENT GAP (provenance ledger: "NOT recovered"). 0.0.0 signals "no
//                       authoritative question set is present" — only 5 preview sample templates exist.
//                       This is honest: it does NOT pretend the missing 25 questions are authored.
// - `formulaVersion`  = the GAME scoring math (design-bible §01–§05). Stable at 1.0.0; the formulas
//                       are verbatim ports and are never altered by this phase.
// - `archetypeModelVersion` = the ANSWER→ARCHETYPE weight matrix. Also a CONTENT GAP (provenance
//                       ledger: "Full diagnostic logic / scoring of answers — NOT recovered").
//                       0.0.0 = no weight matrix exists; the engine runs with an EMPTY matrix and
//                       returns confidence 'none'. This is the explicit, non-invented state.
//
// These zeros are INTENTIONAL and are the Phase 2A answer to "without inventing missing content":
// the contract and engine exist and are fully testable; the missing content is represented as a
// version pin of 0.0.0 rather than fabricated weights or question text.

export const MODEL_VERSIONS = Object.freeze({
  schemaVersion: '1.0.0',
  questionSetVersion: '0.0.0',
  formulaVersion: '1.0.0',
  archetypeModelVersion: '0.0.0',
});

// Returns a fresh copy so callers cannot mutate the frozen canonical object.
export function modelVersions() {
  return { ...MODEL_VERSIONS };
}

// The four required axes (compile-time guard for tests + engine).
export const VERSION_AXES = ['schemaVersion', 'questionSetVersion', 'formulaVersion', 'archetypeModelVersion'];

// Validate that an object carries all four version strings. Pure, non-throwing.
export function validateModelVersions(obj) {
  const errors = [];
  if (!obj || typeof obj !== 'object') return { valid: false, errors: ['modelVersions must be an object'] };
  for (const ax of VERSION_AXES) {
    const v = obj[ax];
    if (typeof v !== 'string' || !/^\d+\.\d+\.\d+$/.test(v)) {
      errors.push(`modelVersions.${ax} must be a semver string (got ${JSON.stringify(v)})`);
    }
  }
  return { valid: errors.length === 0, errors };
}
