// Rune Cast — Daily Oracle (design bible §05). VERBATIM seed/RNG, behavior unchanged.
// No fail state; one cast per day (client date). Deterministic per YYYY-MM-DD.
export function cyrb53(str) {
  let h1 = 0xdeadbeef ^ str.length;
  let h2 = 0x41c6ce57 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507);
  h1 ^= Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507);
  h2 ^= Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

// mulberry32 PRNG from a string seed.
export function mulberry32(seedStr) {
  let a = parseInt(cyrb53(seedStr).slice(0, 8), 16) || 1;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Deterministic daily draw: same 3 runes for every player that day.
export function dailyDraw(dateStr, runeArray) {
  const rng = mulberry32(dateStr);
  const pool = [...runeArray];
  const draw = [];
  for (let i = 0; i < 3 && pool.length; i++) {
    const idx = Math.floor(rng() * pool.length);
    draw.push(pool.splice(idx, 1)[0]);
  }
  const slots = ['Past', 'Present', 'Future'];
  return draw.map((r, i) => ({ slot: slots[i], ...r }));
}

// Streak tiers: 7-day = Seer border, 30-day = gold ink.
export function runeStreakTier(streakDays) {
  if (streakDays >= 30) return 'GOLD_INK';
  if (streakDays >= 7) return 'SEER';
  return 'NONE';
}
