// Phase 2C — Reflection content (SUPPLIED, not invented).
//
// The reflection experience is built from the 5 RECOVERED sample question templates (provenance g6,
// confidence HIGH) plus the 5 game-result context themes. The 5 prompts are reused across scans as
// reflection anchors — this is APPROVED (Path B) content, not invented question text.
//
// PROVENANCE:
//   - 5 reflection prompts: src/data/scans.js RECOVERED_SAMPLE_QUESTIONS (g6, high).
//   - 5 game context themes: GAMES[id].lesson (registry, design-bible FUNNEL-derived).
// No 155-question text is authored; no weights/thresholds are inferred. This file is the single
// content source for the reflection experience and is replaceable by Loki later via the same shape.

import { RECOVERED_SAMPLE_QUESTIONS } from '../data/scans.js';
import { GAMES } from '../games/registry.js';

// Each reflection prompt gets a stable id + the game context it pairs with (funnel-derived).
// NOTE: these pairings are STRUCTURAL (which game themes the prompt echoes), not scoring weights.
const PROMPT_CONTEXT_MAP = [
  { id: 'rp_stall', contextGame: 'hel', axisTheme: 'triage' },
  { id: 'rp_handoff', contextGame: 'jormungandr', axisTheme: 'routing' },
  { id: 'rp_knowledge', contextGame: 'raven', axisTheme: 'knowledge' },
  { id: 'rp_remade', contextGame: 'norns', axisTheme: 'strategy' },
  { id: 'rp_meeting', contextGame: 'fenrir', axisTheme: 'timing' },
];

// Free-form reflection prompts (the only recovered question text). Reused as anchors.
export const REFLECTION_PROMPTS = RECOVERED_SAMPLE_QUESTIONS.map((text, i) => ({
  id: PROMPT_CONTEXT_MAP[i]?.id || `rp_${i}`,
  text,
  contextGame: PROMPT_CONTEXT_MAP[i]?.contextGame || null,
  axisTheme: PROMPT_CONTEXT_MAP[i]?.axisTheme || null,
  source: 'recovered-sample-g6',
  confidence: 'high',
}));

// Game-result context cards (structural, from registry lessons — NOT scored).
export const GAME_CONTEXT_CARDS = Object.values(GAMES).map((g) => ({
  gameId: g.id,
  name: g.name,
  lesson: g.lesson,
  unresolved: !!g.unresolved,
}));

// The single reflection experience (Path B). No scan id split — one honest reflection flow.
// questionSetVersion stays 0.0.0 (content is recovered samples, not the authoritative 25/30 sets).
export const REFLECTION_EXPERIENCE = {
  id: 'reflection-only',
  title: "Loki's Mischief — Reflection Experience",
  promise: 'Reflect on where your ops mischief hides. No score, no archetype, no verdict.',
  prompts: REFLECTION_PROMPTS,
  gameContext: GAME_CONTEXT_CARDS,
  source: 'recovered-sample-g6 + registry',
};

// Pure: how many prompts are required for a "complete" reflection (all of them).
export const totalReflectionPrompts = () => REFLECTION_PROMPTS.length;
