// Diagnostics (six scans) — metadata is canonical (data/arcade-content.json -> diagnostics[]).
// Question TEXT is only partially recoverable: the React artifact (g6) embeds 5 rotating
// SAMPLE question templates and a "10 sample / 25 full / 30 for mischief" structure.
// See docs/scan-content-provenance.md for full provenance. Nothing invented.
export const diagnostics = [
  { id: 'mischief', title: 'Mischief Scan', promise: 'Find the 3 mischiefs hiding in your ops', time: '8 min', audience: 'Founders & COOs', qs: 30 },
  { id: 'fenrir', title: 'Fenrir Bottleneck Audit', promise: 'Locate the chain about to snap', time: '12 min', audience: 'Ops Leads', qs: 25 },
  { id: 'bifrost', title: 'Bifröst Breakdown Assessment', promise: 'Map where handoffs die', time: '10 min', audience: 'Cross-functional teams', qs: 25 },
  { id: 'heimdall', title: 'Heimdall Control Gap', promise: 'Spot what you can’t see until it’s too late', time: '9 min', audience: 'Leadership', qs: 25 },
  { id: 'norns', title: 'Norns Strategy Knot', promise: 'Link daily work to 90-day bets', time: '11 min', audience: 'Founders', qs: 25 },
  { id: 'raven', title: 'Raven Knowledge Rot', promise: 'Find where your second brain is rotting', time: '7 min', audience: 'Knowledge workers', qs: 25 },
];

// Recoverable sample question templates — extracted from g6 artifact survey screen.
// Provenance: g6 (React artifact), confidence: HIGH (verbatim in bundle). These are PREVIEW
// samples; the artifact explicitly states "This preview shows 10 sample questions" and a
// "Full version: 25 questions" / mischief "30 questions" count. Full text is a CONTENT GAP.
export const RECOVERED_SAMPLE_QUESTIONS = [
  'Where does work stall without notice?',
  'Which handoff loses most context?',
  'Who holds knowledge in head not docs?',
  'What decision gets remade weekly?',
  'Which meeting creates no artifact?',
];

// Build a preview question list for a given scan (g6 artifact behavior: mischief=30 slots
// with no inline text; others=10 sample questions cycling the 5 templates).
export function previewQuestions(scanId) {
  if (scanId === 'mischief') {
    // Artifact: Array.from({length:30}) — 30 slots, no inline text recovered.
    return Array.from({ length: 30 }, (_, i) => `Mischief Scan sample Q${i + 1} (FULL TEXT NOT RECOVERED)`);
  }
  return Array.from({ length: 10 }, (_, i) => {
    const base = diagnostics.find((d) => d.id === scanId);
    const t = RECOVERED_SAMPLE_QUESTIONS[i % RECOVERED_SAMPLE_QUESTIONS.length];
    return `${base ? base.title : scanId} sample Q${i + 1}: ${t}`;
  });
}
