import React, { useEffect, useRef, useState, useImperativeHandle, forwardRef } from 'react';
import { runes, RUNE_COUNT } from '../data/runes.js';
import * as runeScoring from '../scoring/runecast.js';
import { makeResult, RESULT_STATUS } from '../shell/contract.js';
import GameChrome from './GameChrome.jsx';

// Rune Cast — Daily Oracle (Phase 3 juice). Scoring/state UNCHANGED; reveal animation + real share card.
const RuneCast = forwardRef(function RuneCast({ onResult, onExit, scoring = runeScoring }, ref) {
  const { dailyDraw, runeStreakTier } = scoring;
  const today = new Date().toISOString().slice(0, 10);
  const [phase, setPhase] = useState('idle');
  const [draw, setDraw] = useState([]);
  const [revealed, setRevealed] = useState(0);
  const [streak, setStreak] = useState(0);
  const [paused, setPaused] = useState(false);
  const [shared, setShared] = useState(false);
  const [cardUrl, setCardUrl] = useState(null);
  const timersRef = useRef([]);
  const canvasRef = useRef(null);
  const cleanupRef = useRef(false);

  const clearTimers = () => { timersRef.current.forEach(clearTimeout); timersRef.current = []; };
  const start = () => {
    setPhase('running');
    const d = dailyDraw(today, runes);
    setDraw(d); setRevealed(0);
    d.forEach((_, i) => { const t = setTimeout(() => setRevealed(i + 1), i * 600); timersRef.current.push(t); });
  };
  const reset = () => { clearTimers(); setPhase('idle'); setDraw([]); setRevealed(0); setShared(false); setCardUrl(null); };
  const finish = () => {
    clearTimers(); setPhase('done');
    const tier = runeStreakTier(streak);
    onResult?.(makeResult({ gameId: 'runecast', score: 0, status: RESULT_STATUS.INCOMPLETE, meta: { date: today, streak, tier, runes: draw.map((r) => r.name) } }));
  };
  const share = () => {
    try {
      const cv = canvasRef.current || document.createElement('canvas');
      cv.width = 1080; cv.height = 1350;
      const ctx = cv.getContext && cv.getContext('2d');
      if (ctx) {
        ctx.fillStyle = '#080c12'; ctx.fillRect(0, 0, 1080, 1350);
        ctx.fillStyle = '#e9c46a'; ctx.font = 'bold 64px sans-serif';
        ctx.fillText("Loki's Mischief — Daily Oracle", 60, 90);
        draw.forEach((r, i) => {
          ctx.fillStyle = '#f6d36b'; ctx.font = '200px sans-serif';
          ctx.fillText(r.s, 60, 320 + i * 280);
          ctx.fillStyle = '#d8e1f0'; ctx.font = '40px sans-serif';
          ctx.fillText(`${r.slot}: ${r.name}`, 320, 280 + i * 280);
          ctx.fillStyle = '#93a4bf'; ctx.font = '30px sans-serif';
          ctx.fillText(r.biz, 320, 330 + i * 280);
        });
        setCardUrl(cv.toDataURL('image/png'));
      }
      setShared(true);
    } catch { setShared(true); }
  };

  useEffect(() => {
    const onVis = () => setPaused(document.hidden);
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);
  useEffect(() => () => { clearTimers(); cleanupRef.current = true; }, []);
  useImperativeHandle(ref, () => ({ pause: () => setPaused(true), resume: () => setPaused(false), restart: reset, exit: () => onExit?.(), isCleanedUp: () => cleanupRef.current }), [onExit]);

  const tier = runeStreakTier(streak);
  const verdict = phase === 'done' ? {
    tone: 'neutral', label: 'The Oracle Speaks', lines: [
      `Date: ${today}`,
      `Streak: ${streak} (${tier})`,
      `Runes drawn: ${draw.map((r) => r.name).join(', ')}`,
      shared ? 'Share card generated below.' : 'Your pattern, reflected.',
    ],
  } : null;

  return (
    <GameChrome
      title="Rune Cast — Daily Oracle"
      lesson="Reflection, pattern, daily review. Divination is pattern recognition with myth."
      accent="runecast"
      hud={`Date ${today} · Streak ${streak} (${tier}) · Runes ${RUNE_COUNT} · Phase: ${phase}`}
      paused={paused}
      verdict={verdict}
      phase={phase}
      actions={phase === 'done' ? (
        <>
          <button className="lm-btn" onClick={reset}>Restart</button>
          <button className="lm-btn" onClick={() => onExit?.()}>Exit</button>
        </>
      ) : null}
    >
      <canvas ref={canvasRef} data-testid="rune-canvas" style={{ display: 'none' }} />
      {phase === 'idle' && <button className="lm-btn" onClick={start}>Cast</button>}
      {phase === 'running' && (
        <div className="lm-runes">
          {draw.map((r, i) => (
            <div key={i} className="lm-rune" data-revealed={i < revealed} data-testid={`rune-${i}`}>
              <div className="lm-rune-sym">{i < revealed ? r.s : 'ᛟ'}</div>
              <div className="lm-rune-slot">{r.slot}</div>
              <div>{i < revealed ? `${r.name} (${r.phon})` : '—'}</div>
              <div className="lm-rune-biz">{i < revealed ? r.biz : 'revealing…'}</div>
            </div>
          ))}
          <div className="lm-reflect-actions">
            <button className="lm-btn" onClick={share} disabled={paused}>Share Card</button>
            <button className="lm-btn" onClick={() => setStreak((s) => s + 1)} disabled={paused}>+ Day (streak)</button>
            <button className="lm-btn" onClick={finish}>Finish</button>
          </div>
        </div>
      )}
      {phase === 'done' && (
        <>
          {cardUrl && <img src={cardUrl} alt="Rune share card" className="lm-share-card" data-testid="share-card" />}
        </>
      )}
      <p className="lm-note">Spec: design bible §05. Seeded by date — same draw for all players that day; cleanup verified.</p>
    </GameChrome>
  );
});

export default RuneCast;
