// Hel — Soul Sorting scoring (design bible §03). VERBATIM, behavior unchanged.
import { HEL_CONFIG } from '../data/soulDeck.js';

// Essence change for a routing decision (correct/incorrect). Shared pool +10 / -10.
export function essenceDelta(isCorrect) {
  return isCorrect ? HEL_CONFIG.ESSENCE_PER_CORRECT : HEL_CONFIG.ESSENCE_PER_WRONG;
}

// Per-soul spawn interval ramps linearly 5.0s (wave 1) -> 2.0s (wave 10).
export function soulInterval(wave) {
  const t = (wave - 1) / Math.max(1, HEL_CONFIG.WAVES - 1);
  return HEL_CONFIG.T_START - (HEL_CONFIG.T_START - HEL_CONFIG.T_END) * t;
}

// Final score: essence 0..800 + accuracy*2 + speed bonus. S rank needs >=90% accuracy.
export function helScore({ essence, correct, total, speedBonus = 0 }) {
  const accuracy = total > 0 ? correct / total : 0;
  const base = Math.max(0, Math.min(800, essence)) + accuracy * 2 + speedBonus;
  const rank = accuracy >= HEL_CONFIG.S_RANK_ACCURACY ? 'S' : accuracy >= 0.7 ? 'A' : 'B';
  return { score: Math.round(base), accuracy, rank };
}
