import React, { useEffect, useRef, useState, useImperativeHandle, forwardRef } from 'react';
import * as sleipScoring from '../scoring/sleipnir.js';
import { makeResult, RESULT_STATUS } from '../shell/contract.js';
import GameChrome from './GameChrome.jsx';

// Sleipnir — Eight-Leg Sprint (Phase 3 juice). Scoring/state UNCHANGED; run bar + coin/parallel readout.
const Sleipnir = forwardRef(function Sleipnir({ onResult, onExit, scoring = sleipScoring }, ref) {
  const { SLEIPNIR_CONFIG: CFG, sleipnirScore, sleipnirSpeed } = scoring;
  const [phase, setPhase] = useState('idle');
  const [dist, setDist] = useState(0);
  const [coins, setCoins] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [paused, setPaused] = useState(false);
  const [multiKey, setMultiKey] = useState('base');
  const rafRef = useRef(0);
  const lastRef = useRef(0);
  const runningRef = useRef(false);
  const pausedRef = useRef(false);
  const elapsedRef = useRef(0);
  const distRef = useRef(0);
  const coinsRef = useRef(0);
  const multiKeyRef = useRef('base');
  const cleanupRef = useRef(false);

  const loop = (ts) => {
    if (!runningRef.current || pausedRef.current) return;
    const dt = lastRef.current ? (ts - lastRef.current) / 1000 : 0;
    lastRef.current = ts;
    const speed = sleipnirSpeed(elapsedRef.current);
    setDist((d) => { const nd = d + speed * dt * 10; distRef.current = nd; return nd; });
    setElapsed((e) => { const ne = e + dt; elapsedRef.current = ne; return ne; });
    if (Math.random() < 0.02) setCoins((c) => { const nc = c + 1; coinsRef.current = nc; return nc; });
    if (Math.random() < 0.001) { finish(); return; }
    rafRef.current = requestAnimationFrame(loop);
  };
  const start = () => {
    setPhase('running'); setDist(0); setCoins(0); setElapsed(0); elapsedRef.current = 0; setMultiKey('base'); lastRef.current = 0;
    runningRef.current = true; pausedRef.current = false;
    rafRef.current = requestAnimationFrame(loop);
  };
  const reset = () => { cancelAnimationFrame(rafRef.current); rafRef.current = 0; runningRef.current = false; setPhase('idle'); setDist(0); setCoins(0); setElapsed(0); };
  const finish = () => {
    cancelAnimationFrame(rafRef.current); rafRef.current = 0; runningRef.current = false;
    setPhase('done');
    const score = sleipnirScore(Math.floor(distRef.current), coinsRef.current, multiKeyRef.current);
    onResult?.(makeResult({ gameId: 'sleipnir', score, status: RESULT_STATUS.INCOMPLETE, meta: { dist: Math.floor(distRef.current), coins: coinsRef.current, multiKey: multiKeyRef.current } }));
  };
  const setParallel = () => setMultiKey((k) => { const nk = k === 'base' ? 'parallel' : 'base'; multiKeyRef.current = nk; return nk; });

  useEffect(() => {
    const onVis = () => { pausedRef.current = document.hidden; setPaused(document.hidden); };
    document.addEventListener('visibilitychange', onVis);
    return () => document.removeEventListener('visibilitychange', onVis);
  }, []);
  useEffect(() => () => { cancelAnimationFrame(rafRef.current); cleanupRef.current = true; }, []);
  useImperativeHandle(ref, () => ({
    pause: () => { pausedRef.current = true; setPaused(true); },
    resume: () => { pausedRef.current = false; setPaused(false); },
    restart: reset, exit: () => onExit?.(), isCleanedUp: () => cleanupRef.current,
  }), [onExit]);

  const score = sleipnirScore(Math.floor(dist), coins, multiKey);
  const verdict = phase === 'done' ? {
    tone: 'neutral', label: 'The Eight Legs Rest', lines: [
      `Distance: ${Math.floor(dist)}`,
      `Coins gathered: ${coins}`,
      `Speed at finish: ${sleipnirSpeed(elapsed).toFixed(1)}`,
      `Mode: ${multiKey === 'parallel' ? 'Parallel (Odin\'s eye)' : 'Single stride'}`,
      'Stop running on one leg — spread the load.',
    ],
  } : null;

  return (
    <GameChrome
      title="Sleipnir — Eight-Leg Sprint"
      lesson="Parallelism, relay, throughput. Stop running on one leg."
      accent="sleipnir"
      hud={`Dist ${Math.floor(dist)} · Coins ${coins} · Speed ${sleipnirSpeed(elapsed).toFixed(1)} · Multi ${multiKey} · Score ${score} · Phase: ${phase}`}
      paused={paused}
      verdict={verdict}
      phase={phase}
      actions={phase === 'done' ? (
        <>
          <button className="lm-btn" onClick={reset}>Restart</button>
          <button className="lm-btn" onClick={() => onExit?.()}>Exit</button>
        </>
      ) : null}
    >
      <div className="lm-run-bar" data-testid="run-bar">
        <i style={{ width: `${Math.min(100, (dist % 1000) / 10)}%` }} />
      </div>
      {phase === 'idle' && <button className="lm-btn" onClick={start}>Start</button>}
      {phase === 'running' && (
        <div>
          <button className="lm-btn" onClick={setParallel} disabled={paused}>Toggle Parallel (Odin's eye)</button>
          <button className="lm-btn" onClick={finish}>Finish Run</button>
          <p className="lm-note"><span className="lm-coin">◈ {coins}</span> {multiKey === 'parallel' && <span className="lm-multi-on">· parallel stride active</span>}</p>
        </div>
      )}
      <p className="lm-note">Spec: design bible §04. Speed {CFG.START_SPEED}→{CFG.MAX_SPEED}; RAF loop + cleanup verified.</p>
    </GameChrome>
  );
});

export default Sleipnir;
