import React from 'react';

// Shared game presentation chrome (Phase 3 games-juice). Wraps each game's interactive body with a
// consistent Norse-themed frame: title + lesson, a HUD score readout (animated delta), a verdict
// screen, and a pause overlay. Presentation ONLY — all scoring/state stays inside the game component.
//
// Props:
//   title, lesson      — header
//   accent             — themed accent key ('fenrir'|'hel'|'jormungandr'|'sleipnir'|'runecast'|'ratatoskr')
//   hud                — string HUD line rendered above the body
//   paused             — show pause overlay when true
//   verdict            — { label, tone, lines[] } shown in place of body when phase==='done'
//   unresolved         — ratatoskr honest frame flag
//   children           — the interactive game body (buttons/board/etc.)
export default function GameChrome({
  title, lesson, accent = 'fenrir', hud, paused = false, verdict, unresolved = false, actions, phase, children,
}) {
  return (
    <section
      className={`lm-game lm-game--${accent}${unresolved ? ' lm-game--unresolved' : ''}`}
      data-phase={phase}
      data-paused={paused}
    >
      <div className="lm-game-head">
        <div>
          <p className="lm-game-kicker">{unresolved ? 'Observable Trial' : 'Norse Trial'}</p>
          <h2 className="lm-game-title">{title}</h2>
        </div>
        {hud && <div className="lm-game-hud" data-testid="game-hud">{hud}</div>}
      </div>
      <p className="lm-lesson">{lesson}</p>

      {verdict ? (
        <div className={`lm-verdict lm-verdict--${verdict.tone || 'neutral'}`} data-testid="game-verdict">
          <div className="lm-verdict-label">{verdict.label}</div>
          {verdict.lines?.map((l, i) => <div key={i} className="lm-verdict-line">{l}</div>)}
        </div>
      ) : (
        <div className="lm-game-body">{children}</div>
      )}

      {actions && <div className="lm-game-actions">{actions}</div>}

      {paused && (
        <div className="lm-pause-overlay" data-testid="pause-overlay">
          <div className="lm-pause-inner">⏸ Paused — return to this trial</div>
        </div>
      )}
    </section>
  );
}
