// localStorage adapter — IMPLEMENTS PersistenceAdapter. Provided as the reference adapter but
// NOT activated as a backend. Phase 0B only requires a replaceable interface to exist; this is
// the client-only default that later phases MAY adopt. No server, no network, try/catch wrapped
// per design bible §00.
import { PersistenceAdapter } from './adapter.js';

export class LocalStorageAdapter extends PersistenceAdapter {
  get(key) {
    try { return globalThis.localStorage ? localStorage.getItem(key) : null; }
    catch { return null; }
  }
  set(key, value) {
    try { if (globalThis.localStorage) localStorage.setItem(key, value); } catch { /* noop */ }
  }
  remove(key) {
    try { if (globalThis.localStorage) localStorage.removeItem(key); } catch { /* noop */ }
  }
}

// Default export is the adapter instance, but it is NOT the only possible implementation.
// Swapping this for a backend adapter later requires no changes to game code (dependency injection).
export const persistence = new LocalStorageAdapter();
